static void expect_true(bool condition, const char* name)
{
    if (!condition) {
        XERROR_PRINTF("FAIL: %s\n", name);
        s_failures++;
    }
}

#if XIMAGECODEC_PNG_ON
/* 在已编码 PNG 的 IHDR 后插入一个元数据块，保持测试夹具只依赖
 * 项目自己的 CRC/字节序工具，不引入平台文件或额外生成器。 */
static uint32_t test_png_chunk_crc(const char type[4],
                                   const uint8_t* data, size_t size)
{
    uint32_t crc = XCrc32_calculate(XCrc32_Algorithm_IsoHdlc,
                                    (const uint8_t*)type, 4);
    return size ? XCrc32_update(XCrc32_Algorithm_IsoHdlc, crc, data, size)
                : crc;
}

static size_t test_png_insert_chunk(const uint8_t* source, size_t sourceSize,
                                    const char type[4], const uint8_t* payload,
                                    size_t payloadSize, uint8_t* output,
                                    size_t outputCapacity)
{
    const size_t prefix = 33u; /* signature + IHDR chunk */
    size_t chunkSize;
    uint32_t crc;
    if (!source || !type || (!payload && payloadSize) || !output ||
        sourceSize < prefix || payloadSize > UINT32_MAX ||
        payloadSize > SIZE_MAX - 12u)
        return 0;
    chunkSize = payloadSize + 12u;
    if (sourceSize > SIZE_MAX - chunkSize ||
        sourceSize + chunkSize > outputCapacity)
        return 0;
    memcpy(output, source, prefix);
    XImageCodecInternal_writeU32BE(output + prefix, (uint32_t)payloadSize);
    memcpy(output + prefix + 4u, type, 4u);
    if (payloadSize)
        memcpy(output + prefix + 8u, payload, payloadSize);
    crc = test_png_chunk_crc(type, payload, payloadSize);
    XImageCodecInternal_writeU32BE(output + prefix + 8u + payloadSize, crc);
    memcpy(output + prefix + chunkSize, source + prefix, sourceSize - prefix);
    return sourceSize + chunkSize;
}
#endif /* XIMAGECODEC_PNG_ON */

static bool test_font_bitmap_info(const XFont* font, XFontBitmapInfo* info)
{
    const XFontFace* face;
    XFontFaceInfo faceInfo;
    if (!info)
        return false;
    face = XFont_face(font);
    memset(&faceInfo, 0, sizeof(faceInfo));
    if (!face || XFontFace_kind(face) != XFontFace_Bitmap ||
        !XFontFace_info_base(face, font, &faceInfo) ||
        faceInfo.m_kind != XFontFace_Bitmap)
        return false;
    *info = faceInfo.m_bitmap;
    return true;
}

static bool test_font_bitmap_load(const XFont* font, uint32_t codepoint,
                                  XFontGlyphDsc* dsc, unsigned char* out,
                                  size_t outSize)
{
    const XFontFace* face;
    if (!dsc || (out && outSize == 0u) || (!out && outSize != 0u))
        return false;
    face = XFont_face(font);
    return face && XFontFace_kind(face) == XFontFace_Bitmap &&
           XFontFace_loadBitmapGlyph_base(face, font, codepoint, dsc, out,
                                          outSize);
}

static bool test_font_outline_info(const XFont* font, XFontOutlineInfo* info)
{
    const XFontFace* face;
    XFontFaceInfo faceInfo;
    if (!info)
        return false;
    face = XFont_face(font);
    memset(&faceInfo, 0, sizeof(faceInfo));
    if (!face || XFontFace_kind(face) != XFontFace_Outline ||
        !XFontFace_info_base(face, font, &faceInfo) ||
        faceInfo.m_kind != XFontFace_Outline)
        return false;
    *info = faceInfo.m_outline;
    return true;
}

static bool test_font_outline_load(const XFont* font, uint32_t codepoint,
                                   XFontOutlineGlyphMetrics* metrics,
                                   const XFontOutlineSink* sink)
{
    const XFontFace* face;
    if (!metrics)
        return false;
    face = XFont_face(font);
    return face && XFontFace_kind(face) == XFontFace_Outline &&
           XFontFace_loadOutlineGlyph_base(face, font, codepoint, metrics,
                                           sink);
}

#if XFONT_OUTLINE_ON && XPAINTER_PATH_ON
static bool test_outline_glyph(uint32_t codepoint,
                               XFontOutlineGlyphMetrics* metrics,
                               const XFontOutlineSink* sink,
                               void* userData)
{
    (void)userData;
    if (!metrics) return false;
    memset(metrics, 0, sizeof(*metrics));
    metrics->advance = 1000;
    metrics->xMin = 100;
    metrics->yMin = 0;
    metrics->xMax = 900;
    metrics->yMax = 800;
    if (codepoint != (uint32_t)'A' || !sink)
        return true;
    if (sink->moveTo && !sink->moveTo(sink->userData, 100.0f, 0.0f)) return false;
    if (sink->lineTo && !sink->lineTo(sink->userData, 500.0f, 800.0f)) return false;
    if (sink->lineTo && !sink->lineTo(sink->userData, 900.0f, 0.0f)) return false;
    if (sink->close && !sink->close(sink->userData)) return false;
    return true;
}

static void test_painter_outline_font(void)
{
    static const XFontOutlineProvider provider = {
        "XOutlineTest", { 1000, 800, 200, 0 }, test_outline_glyph, NULL
    };
    static const XFontOutlineProvider directProvider = {
        "XOutlineDirect", { 1000, 800, 200, 0 }, test_outline_glyph, NULL
    };
    XFont font;
    XFontOutlineInfo info;
    XFontOutlineGlyphMetrics metrics;
    const XFontFace* face;
    XFontFaceInfo faceInfo;
    XImage image;
    XPainter painter;
    int colored = 0;
    int row;
    int col;

    expect_true(XFontOutlineFace_registerProvider(&provider),
                "outline provider registers");
    XFont_init(&font);
    XFont_setFamily(&font, "XOutlineTest");
    XFont_setPixelSize(&font, 20);
    expect_true(test_font_outline_info(&font, &info) && info.unitsPerEm == 1000 &&
                    info.ascent == 800 && info.descent == 200,
                "outline provider exposes design metrics");
    expect_true(test_font_outline_load(&font, (uint32_t)'A', &metrics, NULL) &&
                    metrics.advance == 1000 && metrics.xMax == 900,
                "outline provider exposes glyph metrics");
    face = XFont_face(&font);
    memset(&faceInfo, 0, sizeof(faceInfo));
    expect_true(face && XFontFace_kind(face) == XFontFace_Outline &&
                XFontFace_info_base(face, &font, &faceInfo) &&
                faceInfo.m_kind == XFontFace_Outline &&
                faceInfo.m_outline.unitsPerEm == 1000,
                "font face 父类接口选择轮廓子类");

    {
        XFont directFont;
        XFontOutlineGlyphMetrics directMetrics;
        const XFontFace* directFace;
        expect_true(XFontOutlineFace_registerProvider(&directProvider),
                    "outline 子类直接注册 provider");
        XFont_init(&directFont);
        XFont_setFamily(&directFont, "XOutlineDirect");
        directFace = XFont_face(&directFont);
        memset(&directMetrics, 0, sizeof(directMetrics));
        expect_true(directFace && XFontFace_kind(directFace) == XFontFace_Outline &&
                        XFontFace_loadOutlineGlyph_base(
                            directFace, &directFont, (uint32_t)'A',
                            &directMetrics, NULL) &&
                        directMetrics.advance == 1000,
                    "outline 子类注册接入父类虚函数");
        XFont_deinit_base(&directFont);
    }

    XImage_init_ex(&image, 32, 32, XImageFormat_ARGB32);
    XImage_fillRect(&image, NULL, 0xffffffffu);
    XPainter_init(&painter, NULL);
    expect_true(XPainter_begin_image(&painter, &image),
                "outline painter begins raster");
    XPainter_setFont(&painter, &font);
    expect_true(XPainter_drawText(&painter, 2, 24, "A", 0xff0080ffu),
                "outline glyph draws with operation color");
    expect_true(XPainter_textWidth(&font, "A") == 20 &&
                    XPainter_textAscent(&font) == 16 &&
                    XPainter_textDescent(&font) == 4,
                "outline metrics scale from unitsPerEm");
    for (row = 0; row < 32; ++row)
        for (col = 0; col < 32; ++col)
            if (XImage_pixel(&image, col, row) == 0xff0080ffu)
                ++colored;
    expect_true(colored > 0, "outline path reaches raster image");

#if XFONT_BUILTIN_OUTLINE_ON
    {
        XFont commonFont;
        XFontOutlineInfo commonInfo;
        XFontOutlineGlyphMetrics commonMetrics;
        XFont_init(&commonFont);
        XFont_setFamily(&commonFont, "XFontOutlineCommon");
        XFont_setPixelSize(&commonFont, 20);
        expect_true(test_font_outline_info(&commonFont, &commonInfo) &&
                        commonInfo.unitsPerEm == 1000 &&
                        commonInfo.ascent == 1160,
                    "内置常用汉字轮廓字库提供度量");
        expect_true(test_font_outline_load(&commonFont, 0x4E2Du,
                                           &commonMetrics, NULL) &&
                        commonMetrics.advance > 0,
                    "内置常用汉字轮廓字库读取汉字");
        expect_true(test_font_outline_load(&commonFont, 0x4F60u,
                                           &commonMetrics, NULL) &&
                        commonMetrics.advance > 0,
                    "内置轮廓字库包含常用字");
        XImage_fillRect(&image, NULL, 0xffffffffu);
        colored = 0;
        XPainter_setFont(&painter, &commonFont);
        expect_true(XPainter_drawText(&painter, 2, 24,
                                      "\xE4\xB8\xAD\xE6\x96\x87",
                                      0xff0080ffu),
                                      "内置中文轮廓字形完成栅格化");
        for (row = 0; row < 32; ++row)
            for (col = 0; col < 32; ++col)
                if (XImage_pixel(&image, col, row) != 0xffffffffu)
                    ++colored;
        expect_true(colored > 0, "内置中文轮廓字形实际写入像素");
        XFont_deinit_base(&commonFont);
    }
#endif /* XFONT_BUILTIN_OUTLINE_ON */

#if XFONT_OUTLINE_FILE_ON && XIMAGECODEC_ON
    {
        /* Minimal XFO1 triangle fixture: one cmap entry, one glyph, four
           commands. It exercises the same file path used by PC deployments. */
        static const uint8_t xfo[] = {
            'X','F','O','1', 1,0, 0,0, 0xe8,0x03, 0x20,0x03, 0xc8,0x00, 0,0,
            1,0, 1,0, 36,0,0,0, 44,0,0,0, 64,0,0,0, 16,0,0,0,
            0x41,0,0,0, 0,0, 0,0,
            0xe8,0x03,0,0, 100,0, 0,0, 0x84,0x03, 0x20,0x03,
            0,0,0,0, 4,0, 0,0,
            0, 100,0, 0,0, 1, 0x90,1, 0x20,3,
            1, 0x90,1, 0xe0,0xfc, 4
        };
        const char* fileName = "xgui_outline_test.xfo";
        XFont fileFont;
        XFontOutlineInfo fileInfo;
        XFontOutlineGlyphMetrics fileMetrics;
        expect_true(test_write_binary_file(fileName, xfo, sizeof(xfo), true),
                    "XFO1 fixture writes");
        XFont_init(&fileFont);
        XFont_setFamily(&fileFont, fileName);
        expect_true(test_font_outline_info(&fileFont, &fileInfo) &&
                        fileInfo.unitsPerEm == 1000,
                    "XFO1 file header parses");
        expect_true(test_font_outline_load(&fileFont, (uint32_t)'A',
                                           &fileMetrics, NULL) &&
                        fileMetrics.advance == 1000 && fileMetrics.yMax == 800,
                    "XFO1 file glyph parses");
        XFont_deinit_base(&fileFont);
        remove(fileName);
    }
#endif /* XFONT_OUTLINE_FILE_ON && XIMAGECODEC_ON */

    XPainter_end(&painter);
    XPainter_deinit(&painter);
    XImage_deinit_base(&image);
    XFont_deinit_base(&font);
}
#endif /* XFONT_OUTLINE_ON && XPAINTER_PATH_ON */

static void test_picture_put_u32(uint8_t* p, uint32_t value)
{
    p[0] = (uint8_t)value;
    p[1] = (uint8_t)(value >> 8);
    p[2] = (uint8_t)(value >> 16);
    p[3] = (uint8_t)(value >> 24);
}

static uint32_t test_picture_checksum(const uint8_t* data, uint32_t size)
{
    uint32_t hash = 2166136261u;
    uint32_t i;
    for (i = 0; i < size; ++i)
    {
        uint8_t value = (i >= 36u && i < 40u) ? 0u : data[i];
        hash ^= value;
        hash *= 16777619u;
    }
    return hash;
}

/** @brief Picture save_device 短写夹具；模拟 QIODevice::write 的部分写入。 */
static int64_t g_picture_save_short_write_calls;
static int64_t picture_save_short_write(XIODevice* device,
                                        const char* data,
                                        int64_t len)
{
    (void)device;
    (void)data;
    g_picture_save_short_write_calls++;
    return len > 1 ? len / 2 : len;
}

static void picture_save_short_write_device_init(XIODevice* device,
                                                 XVtable* vtable,
                                                 void** table)
{
    XVtable* base;
    size_t i;
    XIODevice_init(device);
    base = XIODevice_class_init();
    for (i = 0; i < (size_t)XIODevice_VTABLE_SIZE; ++i)
        table[i] = base->data[i];
    XVtable_init_stack(vtable, table, (size_t)XIODevice_VTABLE_SIZE);
    vtable->size = base->size;
    XClassGetVtable(device) = vtable;
    table[EXIODevice_WriteData] = (void*)picture_save_short_write;
}

static bool test_picture_invalid_u32(const XPicture* source,
                                     uint32_t payloadOffset,
                                     uint32_t value)
{
    XPicture candidate;
    uint8_t* data;
    uint32_t size;
    bool invalid;
    if (!source) return false;
    size = XPicture_size(source);
    if (!XPicture_data(source) || size < XPICTURE_HEADER_SIZE ||
        payloadOffset > size || size - payloadOffset < 4u)
        return false;
    data = (uint8_t*)XMalloc_System(size);
    if (!data) return false;
    memcpy(data, XPicture_data(source), size);
    test_picture_put_u32(data + payloadOffset, value);
    test_picture_put_u32(data + 36u, 0u);
    test_picture_put_u32(data + 36u, test_picture_checksum(data, size));
    XPicture_init(&candidate, -1);
    XPicture_setData(&candidate, (const char*)data, size);
    invalid = !XPicture_isValidStream(&candidate);
    XPicture_deinit_base(&candidate);
    XFree_System(data);
    return invalid;
}

/** @brief 校验 Picture 状态记录的有限值、枚举与启用位防护。 */
static void test_picture_malformed_state_records(void)
{
    XPicture picture;
    XImageTransform matrix;

    memset(&matrix, 0, sizeof(matrix));
    matrix.m11 = 1.0f;
    matrix.m22 = 1.0f;
    matrix.m33 = 1.0f;

    XPicture_init(&picture, -1);
    expect_true(XPicture_recordSetOpacity(&picture, 0.5f),
                "malformed-state fixture records opacity");
    expect_true(test_picture_invalid_u32(&picture, 48u, 0x7fc00000u),
                "picture validator rejects NaN opacity");
    XPicture_clearCommands(&picture);

    expect_true(XPicture_recordSetCompositionMode(&picture,
                        (int)XPainterCompositionMode_SourceOver),
                "malformed-state fixture records composition mode");
    expect_true(test_picture_invalid_u32(&picture, 48u, 0xffffffffu),
                "picture validator rejects out-of-range composition mode");
    XPicture_clearCommands(&picture);

    expect_true(XPicture_recordSetBrushOrigin(&picture, 1.0f, 2.0f),
                "malformed-state fixture records brush origin");
    expect_true(test_picture_invalid_u32(&picture, 52u, 0x7fc00000u),
                "picture validator rejects NaN brush origin");
    XPicture_clearCommands(&picture);

    expect_true(XPicture_recordSetTransform(&picture, &matrix, true),
                "malformed-state fixture records transform");
    expect_true(test_picture_invalid_u32(&picture, 84u, 2u),
                "picture validator rejects invalid transform enable bit");
    XPicture_clearCommands(&picture);

    expect_true(XPicture_recordSetBackgroundMode(&picture, 0),
                "malformed-state fixture records background mode");
    expect_true(test_picture_invalid_u32(&picture, 48u, 2u),
                "picture validator rejects invalid background mode");
    XPicture_deinit_base(&picture);

#if XPAINTER_BRUSH_ON
    {
        XPainterGradient gradient;
        XPicture_init(&picture, -1);
        XPainterGradient_initLinear(&gradient, 0.0f, 0.0f, 4.0f, 0.0f);
        XPainterGradient_addStop(&gradient, 0.0f, 0xffffffffu);
        expect_true(XPicture_recordSetBrushGradient(&picture, &gradient),
                    "malformed-gradient fixture records gradient");
        /* Picture header (40) + record header (8) + fixed gradient payload
           (48) reaches the first stop position at byte 96. */
        expect_true(test_picture_invalid_u32(&picture, 96u, 0x7fc00000u),
                    "picture validator rejects NaN gradient stop position");
        XPicture_deinit_base(&picture);
    }
#endif /* XPAINTER_BRUSH_ON */

    XPicture_init(&picture, -1);
    expect_true(XPicture_recordDrawText(&picture, 0, 12, "A", 0xffffffffu,
                                        NULL),
                "malformed-state fixture records text");
    expect_true(test_picture_invalid_u32(&picture, 60u, 0x10000u),
                "picture validator rejects oversized text payload");
    XPicture_deinit_base(&picture);

#if XPAINTER_PATH_ON
    {
        XPainterPath path;
        XPicture_init(&picture, -1);
        XPainterPath_init(&path);
        expect_true(XPainterPath_moveTo(&path, 0.0f, 0.0f) &&
                    XPainterPath_cubicTo(&path, 1.0f, 0.0f,
                                         2.0f, 1.0f, 3.0f, 3.0f) &&
                    XPicture_recordDrawPath(&picture,
                                            (int)XPainterPathOp_Draw,
                                            &path),
                    "malformed-path fixture records cubic path");
        /* The first CurveToData starts at header 40 + record 8 + path
           header 8 + MoveTo 12 + CurveTo 12 = byte 80. */
        expect_true(test_picture_invalid_u32(
                        &picture, 80u, (uint32_t)XPainterPathElement_MoveTo),
                    "picture validator rejects interrupted cubic path");
        XPainterPath_deinit(&path);
        XPicture_deinit_base(&picture);
    }
#endif /* XPAINTER_PATH_ON */
}

#if XWIDGET_ON && XFRAME_ON
/** @brief XFrame 几何、样式和 short 线宽存储契约测试（对标 Qt 6.8 QFrame）。 */
static void test_frame_contract(void)
{
    XFrame frame;
    XRect wanted;
    XRect got;
    int style;

    memset(&frame, 0, sizeof(frame));
    XFrame_init(&frame, NULL, 0);
    XWidget_setGeometry(&frame.m_base, 0, 0, 100, 80);
    XFrame_setFrameStyle(&frame,
                         (int)XFrameShape_Box | (int)XFrameShadow_Raised);
    XFrame_setLineWidth(&frame, 2);
    XFrame_setMidLineWidth(&frame, 1);
    expect_true(XFrame_frameWidth(&frame) == 5,
                "QFrame Box/Raised frameWidth=2*line+mid");

    style = 0x14000 | (int)XFrameShape_Panel | (int)XFrameShadow_Sunken;
    XFrame_setFrameStyle(&frame, style);
    expect_true(XFrame_frameStyle(&frame) == (int)(short)style &&
                XFrame_frameShape(&frame) == XFrameShape_Panel &&
                XFrame_frameShadow(&frame) == XFrameShadow_Sunken,
                "QFrame setFrameStyle 按 short 截断并按掩码读取形状/阴影");

    wanted.x = 10;
    wanted.y = 8;
    wanted.width = 60;
    wanted.height = 40;
    XFrame_setFrameRect(&frame, &wanted);
    got = XFrame_frameRect(&frame);
    expect_true(got.x == wanted.x && got.y == wanted.y &&
                got.width == wanted.width && got.height == wanted.height,
                "QFrame setFrameRect 非全控件矩形往返保持一致");

    XFrame_setFrameRect(&frame, NULL);
    got = XFrame_frameRect(&frame);
    expect_true(got.x == 0 && got.y == 0 && got.width == 100 && got.height == 80,
                "QFrame null frameRect 回退到控件矩形");

    XFrame_setLineWidth(&frame, -1);
    expect_true(XFrame_lineWidth(&frame) == (int)(short)-1,
                "QFrame setLineWidth 按 short 语义保存负值");
    XFrame_setMidLineWidth(&frame, 65537);
    expect_true(XFrame_midLineWidth(&frame) == (int)(short)65537,
                "QFrame setMidLineWidth 按 short 语义保存溢出值");
    XFrame_deinit_base(&frame);
}
#endif /* XWIDGET_ON && XFRAME_ON */

/** @brief 统计图像中与指定背景色不同的像素数量。 */
static size_t image_count_non_background(const XImage* image,
                                         uint32_t background)
{
    size_t count = 0;
    int x;
    int y;
    if (!image) return 0;
    for (y = 0; y < XImage_height(image); ++y) {
        for (x = 0; x < XImage_width(image); ++x) {
            if (XImage_pixel(image, x, y) != background)
                ++count;
        }
    }
    return count;
}

/** @brief 统计图像中与指定 ARGB 颜色完全一致的像素数量。 */
static size_t image_count_color(const XImage* image, uint32_t color)
{
    size_t count = 0;
    int x;
    int y;
    if (!image) return 0;
    for (y = 0; y < XImage_height(image); ++y) {
        for (x = 0; x < XImage_width(image); ++x) {
            if (XImage_pixel(image, x, y) == color)
                ++count;
        }
    }
    return count;
}

/** @brief 返回图像中非背景像素的水平包围范围。 */
static bool image_non_background_x_bounds(const XImage* image,
                                          uint32_t background,
                                          int* outMinX, int* outMaxX)
{
    int x;
    int y;
    int minX = image ? XImage_width(image) : 0;
    int maxX = -1;
    if (!image) return false;
    for (y = 0; y < XImage_height(image); ++y) {
        for (x = 0; x < XImage_width(image); ++x) {
            if (XImage_pixel(image, x, y) != background) {
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
            }
        }
    }
    if (outMinX) *outMinX = minX;
    if (outMaxX) *outMaxX = maxX;
    return maxX >= 0;
}

